# Use a SAT approach with pysat to find a graph with 19 vertices, 26 edges, girth>=7, 3-colorable
from pysat.solvers import Minisat22
from pysat.formula import CNF, IDPool
from itertools import combinations

n = 19
# edge variables e_{u,v}
vpool = IDPool()
def E(u,v):
    if u>v: u,v=v,u
    return vpool.id(('e',u,v))
def C(v,c):
    return vpool.id(('c',v,c))

solver = Minisat22()

# 3-coloring: for each vertex exactly one color among 0,1,2 (at least one)
for v in range(n):
    solver.add_clause([C(v,0), C(v,1), C(v,2)])

# For each potential edge, if edge present, adjacent vertices different colors
for u,v in combinations(range(n),2):
    for c in range(3):
        # e_uv -> not(C(u,c) and C(v,c))
        solver.add_clause([-E(u,v), -C(u,c), -C(v,c)])

