import itertools

def cycles_of_length(n, k):
    # vertex sequences v0<... fix v0 as smallest
    verts = list(range(n))
    for combo in combinations(verts, k):
        # fix combo[0] as starting, enumerate permutations of the rest, break symmetry
        first = combo[0]
        rest = combo[1:]
        seen = set()
        for perm in itertools.permutations(rest):
            seq = (first,)+perm
            # normalize: smallest rotation + direction, but we fixed first as smallest
            # direction: second < last to avoid reverse duplicate
            if perm[0] < perm[-1]:
                yield seq

count = 0
for k in range(3,7):
    for cyc in cycles_of_length(n,k):
        # forbid all edges present
        clause = []
        for i in range(k):
            u,v = cyc[i], cyc[(i+1)%k]
            clause.append(-E(u,v))
        solver.add_clause(clause)
        count += 1
print("cycle clauses:", count)

