# Let me run with longer timeout and fewer seeds
import random
from collections import deque

def bfs_dist(adj, s, t, limit):
    if s == t: return 0
    visited = {s: 0}
    q = deque([s])
    while q:
        u = q.popleft()
        if visited[u] >= limit: break
        for v in adj[u]:
            if v not in visited:
                visited[v] = visited[u]+1
                if v == t: return visited[v]
                q.append(v)
    return float('inf')

def is_3_colorable(n, edges):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    colors = [-1]*n
    order = sorted(range(n), key=lambda x: -len(adj[x]))
    def bt(i):
        if i == n: return True
        v = order[i]
        used = set(colors[u] for u in adj[v] if colors[u]!=-1)
        for c in range(3):
            if c not in used:
                colors[v]=c
                if bt(i+1): return True
                colors[v]=-1
        return False
    return bt(0)

def local_search(n, seed, iters=3000):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    edges = []
    pairs = [(i,j) for i in range(n) for j in range(i+1,n)]
    random.shuffle(pairs)
    for (u,v) in pairs:
        d = bfs_dist(adj, u, v, 6)
        if d >= 6:
            adj[u].add(v); adj[v].add(u)
            edges.append((u,v))
    best_edges = list(edges)
    for it in range(iters):
        if len(edges) >= 26:
            return edges
        if not edges: break
        # remove 1-2 random edges then re-fill
        k = random.choice([1,2,3])
        removed = []
        for _ in range(k):
            if not edges: break
            idx = random.randrange(len(edges))
            u,v = edges.pop(idx)
            adj[u].discard(v); adj[v].discard(u)
            removed.append((u,v))
        cand = [(i,j) for i in range(n) for j in range(i+1,n) if j not in adj[i]]
        random.shuffle(cand)
        for (a,b) in cand:
            d = bfs_dist(adj, a, b, 6)
            if d >= 6:
                adj[a].add(b); adj[b].add(a)
                edges.append((a,b))
        if len(edges) > len(best_edges):
            best_edges = list(edges)
    return best_edges

best_global = []
for seed in range(50):
    edges = local_search(19, seed, 1500)
    if len(edges) > len(best_global):
        best_global = edges
    if len(edges) >= 26:
